def solve_m(m):
    # 1. Check if T is an integer
    if (m * (m + 1)) % 6 != 0:
        return False, None

    T = (m * (m + 1)) // 6
    S = list(range(1, m + 1))

    # Helper function to find a subset summing to target from available_elements
    # Returns one such subset, or None if none exists.
    # Uses recursion/backtracking for subset sum.
    def find_subset_sum(target, elements):
        if target == 0:
            return []
        if not elements or target < 0:
            return None

        # Use memoization based on (target, frozenset(elements)) if performance is critical,
        # but since elements change and are subsets of {1..m}, simple recursion might suffice given m <= 30.

        # Optimization: sort elements descendingly to prune faster
        elements_sorted = sorted(elements, reverse=True)

        def search(target, index, current_subset):
            if target == 0:
                return list(current_subset)
            if index == len(elements_sorted) or target < 0:
                return None

            element = elements_sorted[index]

            # Option 1: Include the current element
            result = search(target - element, index + 1, current_subset + [element])
            if result is not None:
                return result

            # Option 2: Exclude the current element
            result = search(target, index + 1, current_subset)
            if result is not None:
                return result

            return None

        # We enforce non-empty requirement implicitly by requiring T > 0, which is true for m >= 1.
        result_set = search(target, 0, [])
        return result_set

    # 2. Search for subset X summing to T
    X = find_subset_sum(T, S)

    if X is None:
        return False, None

    # 3. Define the remaining set S' = S \ X
    remaining_elements = [x for x in S if x not in X]

    # 4. Search for subset Y summing to T in S'
    Y = find_subset_sum(T, remaining_elements)

    if Y is not None:
        return True, (X, Y)
    else:
        return False, None

M_range = range(16, 31)
results = {}
for m in M_range:
    found, details = solve_m(m)
    results[m] = found

print(results)

